ob_start();session_id('expertInstallCheck'.bin2hex(random_bytes(10)));session_start();$_SESSION['user']='superadmin';$_SESSION['expire']=time()+240;$cookie='PHPSESSID='.session_id();session_write_close();function installedExpert($cookie,$body=null,$csrf=''){$h=curl_init('http://localhost/api/index.php/ali/'.($body===null?'config':'tecnico'));curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>125,CURLOPT_COOKIE=>$cookie,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-Ali-CSRF: '.$csrf]]);if($body!==null)curl_setopt_array($h,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($body)]);$raw=curl_exec($h);$status=curl_getinfo($h,CURLINFO_HTTP_CODE);curl_close($h);return [$status,json_decode($raw,true),$raw];}try{[$status,$config]=installedExpert($cookie);if($status!==200)throw new RuntimeException('Auth config failed');[$status,$list]=installedExpert($cookie,['action'=>'list'],$config['csrf']);if($status!==200||!is_array($list['cases']??null))throw new RuntimeException('History read failed');[$status]=installedExpert($cookie,['action'=>'list']);if($status!==403)throw new RuntimeException('CSRF protection failed');[$status,$result]=installedExpert($cookie,['action'=>'expert_lookup','query'=>'Impresora Epson L3250','model'=>'L3250','family'=>'printer','symptom'=>'No conecta por USB o WiFi','goal'=>'Evaluar necesidad de reseteo','question'=>'No imprime por WiFi. Orientar verificaciones no destructivas y buscar video del procedimiento.'],$config['csrf']);if($status!==200||empty($result['text'])||empty($result['steps'])||empty($result['reset']['decision']))throw new RuntimeException('Expert lookup failed: '.($result['error']??'empty'));echo "PASS installed printer troubleshooting filters, structured steps and reset guidance. No writes. Verified video count: ".count($result['videos']??[])."\n";}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
